from wd_common import *
i=4
Z=lambda q,a:[('z',q),('b',a)]
def bell(top='nandi',s=1):
    tops={'nandi':'<ellipse cy="-58" rx="10" ry="6" fill="#a8841f"/><circle cx="8" cy="-62" r="4" fill="#a8841f"/>','garuda':'<path d="M-10 -56 l10 -14 l10 14z" fill="#a8841f"/><path d="M-14 -58 l-8 -6 M14 -58 l8 -6" stroke="#a8841f" stroke-width="3"/>','plain':''}
    return f'<g transform="scale({s})"><path d="M-20 0 q0 -40 20 -40 q20 0 20 40z" fill="#c9a227"/><rect x="-3" y="-54" width="6" height="14" fill="#a8841f"/><circle cy="5" r="5" fill="#a8841f"/>{tops[top]}</g>'
def hbell(): return '<path d="M0 -80 v30" stroke="#5a3a1a" stroke-width="3"/><path d="M-26 0 q0 -50 26 -50 q26 0 26 50z" fill="#c9a227"/><path d="M0 0 v10" stroke="#a8841f" stroke-width="5"/>'
def waves(cx,cy): return ''.join(f'<path d="M{cx+r} {cy-r*.6} q{r*.4} {r*.6} 0 {r*1.2}" stroke="#e0a800" stroke-width="2" fill="none"/>' for r in (30,46,62))
def conch(): return '<path d="M-16 0 q-10 -20 6 -30 q20 -6 22 14 q-4 16 -28 16z" fill="#f4f1ea"/>'
fw=foreword(i,['Walk into a temple and the first thing many people do is reach up and ring the great bell at the door. In the pūjā at home, the left hand rings a small bell while the right waves the lamp. The <b>ghaṇṭā</b> is one of the oldest objects of worship, and its sound is the first offering.',
 'This part explains the bell’s name and metal, the bells of the doorway and of the hand, the emblems on the handle, when it is rung and why, what is said about sound driving away evil and calling the gods, the vow bells, and the teachers’ readings.',
 'Previous: '+L('/why-do-we/coconut/','the coconut')+'. Next: '+L('/why-do-we/pradakshina/','pradakṣiṇā')+'. The bell rings at '+L('/why-do-we/arati/','ārati')+'.'],Z('Do the gods need waking?','The tradition says the bell announces you. Whether the god or your own mind wakes up, you decide.'))
gl=glance([('Name','Ghaṇṭā (Kannaḍa gaṇṭe)'),('Metal','Bell metal: bronze, sometimes pañcaloha'),('Kinds','Great hanging bells; small hand bells'),('Handle','Emblem of the deity: Nandi, Garuḍa, Hanumān, conch-discus'),('Doorway','Rung on entering the temple'),('In pūjā','During bathing, offering, incense and ārati'),('Hand','Usually rung with the left hand'),('Said to','Drive away evil, invite the gods, focus the mind'),('With it','Conch, drum, clapping, song'),('Vows','Bells offered at shrines for wishes fulfilled')],
 S('A great hanging bell at a temple door and a small hand bell with Nandi on top',g(160,200,1.6,hbell())+waves(200,150)+g(400,215,1.8,bell('nandi'))+g(500,200,1,lamp()),'#fff3cf',215),Z('Why the left hand?','The right is busy with the lamp. And the left is said to suit the bell.'),'The first offering <b>is sound</b>.')
name=reading('name','NAME AND METAL','Ghaṇṭā and bell metal',S('Molten metal poured into a mould beside finished bells',g(150,200,1.4,'<path d="M-30 0 h60 l-10 -40 h-40z" fill="#5a3a1a"/>')+'<path d="M170 120 q20 20 10 60" stroke="#e08a2a" stroke-width="6" fill="none"/>'+''.join(g(320+k*70,215,1+0.1*k,bell('plain')) for k in range(3)),'#fff3cf',215),
 ['<b>Ghaṇṭā.</b> The Sanskrit word for bell; Kannaḍa <b>gaṇṭe</b>, Tamiḻ maṇi.','<b>Bell metal.</b> Temple bells are cast in bronze (kaṃsa), an alloy of copper and tin, prized for a long, clear ring.','<b>Pañcaloha.</b> Some are cast in pañcaloha, a five-metal alloy used for icons. (As described.)','<b>Craft.</b> Families of bell-founders in many regions keep the old casting methods.','<b>Old.</b> Bells appear across Hindu, Buddhist and Jain worship.'],Z('Does the metal matter?','Ring a tin can and a bronze bell. You will hear the answer.'),'A metal <b>that sings</b>.')
door=reading('door','THE DOORWAY BELL','Announcing yourself',S('A devotee reaching up to ring a large bell at a temple entrance',g(280,215,2,'<rect x="-70" y="-160" width="140" height="160" fill="#e9d6c0"/><rect x="-40" y="-120" width="80" height="120" fill="#3a1a0a"/>')+g(280,90,1,hbell())+g(200,215,1.4,person('#c0392b'))+'<path d="M206 140 l60 -40" stroke="#e8c3a0" stroke-width="6"/>'+waves(300,80),'#fff3cf',230),
 ['<b>At the entrance.</b> Most temples hang one or more large bells at the door or in front of the sanctum.','<b>Announcing.</b> Ringing it is like knocking: the devotee announces his arrival.','<b>Turning inward.</b> Teachers say the sound also clears the mind of outside thoughts as you enter. (Interpretation.)','<b>Gently.</b> One or a few rings; not a contest.','<b>Leaving.</b> Some ring again on leaving; others do not. (Customs differ.)'],Z('Can kids ring it?','They love to. Lift them up, one ring each.'),'Knock <b>on the god’s door</b>.')
hand=reading('hand','THE HAND BELL','The bell of the pūjā',S('A hand bell with Garuḍa on top, rung while a lamp is waved',g(180,215,2,bell('garuda'))+waves(220,140)+g(380,215,1.4,person('#f4f1ea'))+g(400,150,.8,lamp()),'#fff3cf',215),
 ['<b>Small bell.</b> Home and temple pūjās use a hand bell, held by the handle.','<b>Left hand.</b> It is commonly rung with the left hand, while the right hand offers.','<b>At key moments.</b> It rings during the bath (abhiṣeka), incense, lamp, food offering and ārati.','<b>Steady.</b> A steady, unbroken ring is preferred to loud jangling. (Common teaching.)','<b>Kept clean.</b> The bell is part of the pūjā set, cleaned with the lamps.'],Z('How long should it ring?','Through the offering. When the offering stops, the bell stops.'),'The bell <b>keeps the pūjā’s time</b>.')
handle=cards('emblems','THE HANDLE','Who sits on top',fig_row('Bells with Nandi, Garuḍa, and plain handles',[(bell('nandi'),1.2),(bell('garuda'),1.2),(bell('plain'),1.2),(conch(),1.2)],['Nandi','Garuḍa','plain','conch'],gy=150),
 [('🐂','Nandi','For Śiva worship, the bull Nandi sits on the handle.'),('🦅','Garuḍa','For Viṣṇu worship, Garuḍa; sometimes Hanumān.'),('🐚','Conch and discus','Viṣṇu’s emblems on some bells.'),('🔱','Trident','Some Śiva and Devī bells carry the trident.'),('🔔','Plain','Many household bells are plain.'),('🛕','Matching','Families keep the bell of their own deity.')],None,'The god’s mount <b>rides the bell</b>.',intro='The figure on the handle usually matches the deity worshipped.')
why=reading('why','WHY RING IT','Driving away, inviting in',S('Dark shapes leaving and bright figures arriving as the bell rings',g(280,215,1.8,bell('plain'))+waves(310,150)+''.join(f'<circle cx="{60+k*30}" cy="{100+k*10}" r="10" fill="#3a3a4a" opacity=".6"/>' for k in range(4))+''.join(g(420+k*40,130-k*10,.5,flame()) for k in range(3)),'#20243a',215),
 ['<b>A common verse.</b> A verse widely recited while ringing the bell says it is rung so that the gods may come and the demons may go. (Paraphrase of a common pūjā verse.)','<b>Clearing.</b> The sound is believed to clear the place of inauspicious forces.','<b>Inviting.</b> It welcomes the divine presence into the worship.','<b>Covering noise.</b> Practically, it drowns out other sounds, so the worshipper is not distracted.','<b>The god as listener.</b> Pūjā offers to all senses: sight (lamp), smell (incense), taste (food), touch (flowers) and hearing (bell).'],Z('So the bell is a guard?','A doorman for the gods. Friends in, troublemakers out.'),'Gods in, <b>trouble out</b>.')
om=reading('sound','THE SOUND','Resonance and attention',S('Sound waves spreading from a bell into a still mind',g(160,215,1.8,bell('plain'))+waves(200,150)+g(420,215,1.6,person('#1d4f8a',seat=True))+'<circle cx="420" cy="140" r="30" fill="none" stroke="#e0a800" stroke-width="2"/>','#20243a',215),
 ['<b>Nāda.</b> Indian thought gives sound a high place: creation itself is linked with sound, and Oṃ with the first sound. (Teaching.)','<b>Resonance.</b> A good bell’s ring fades slowly, like the hum at the end of Oṃ; teachers compare them. (Interpretation.)','<b>Attention.</b> Following the fading ring draws the mind into the present moment. (Common teaching.)','<b>Not science claims.</b> Popular claims that bells “balance the brain” are not established; we leave them aside.','<b>Simple.</b> The plain point: it is a beautiful sound offered to God.'],Z('Does it really calm the mind?','Try it: ring once and listen until it is gone. Then tell me.'),'Listen <b>till it fades</b>.')
when=cards('when','WHEN IT IS RUNG','Moments of the pūjā',fig_row('Water pot, incense, lamp, food and lamp plate',[('<path d="M-12 0 h24 l-4 -24 h-16z" fill="#4aa3df"/>',1.2),('<path d="M0 0 v-40" stroke="#7a3b1f" stroke-width="3"/><path d="M0 -40 q6 -10 0 -20" stroke="#9a9a9a" stroke-width="2" fill="none"/>',1.2),(lamp(),1),('<ellipse rx="26" ry="8" fill="#2f8a3a"/><circle cy="-6" r="8" fill="#f4f1ea"/>',1.2),(conch(),1.2)],['bath','incense','lamp','food','ārati'],gy=150),
 [('💧','Abhiṣeka','While the deity is bathed.'),('🌫️','Dhūpa','While incense is offered.'),('🪔','Dīpa','While the lamp is shown.'),('🍚','Naivedya','While the food is offered, often with the curtain drawn.'),('🔥','Ārati','Throughout the waving of lights.'),('🚪','Entering','At the temple door.')],None,'The bell <b>marks each offering</b>.',intro='Practice varies; these are the moments the bell is most often heard.')
vow=reading('vows','VOW BELLS','Thousands of bells',S('Rows and rows of bells hanging at a hill shrine',''.join(g(60+k*45,60+(k%3)*40,.5+0.1*(k%2),hbell()) for k in range(11))+''.join(g(80+k*45,170+(k%2)*30,.5,hbell()) for k in range(10)),'#fff3cf',230),
 ['<b>Offered bells.</b> At some shrines devotees tie or hang bells after a wish is granted.','<b>Golu Devatā.</b> The shrines of Golu Devatā in Uttarākhaṇḍ are famous for their tens of thousands of bells.','<b>Temple gifts.</b> Families donate large bells to temples, often inscribed with their names.','<b>Old bells.</b> Some temple bells are centuries old and treasured.','<b>Elsewhere.</b> Bells are offered in Buddhist and Jain shrines too.'],Z('Thousands of bells? Isn’t it noisy?','When the wind blows, the hill sings.'),'Wishes <b>that ring</b>.')
st=story('story','THE QUIET BELL','Arjun and the doorway bell',strip('Three panels: a boy rings the bell wildly; grandmother shows him one ring; both listen',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,70,.6,hbell())+g(60,180,.7,person('#1d4f8a')),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,70,.6,hbell())+g(40,180,.7,person('#f4f1ea'))+g(100,180,.6,person('#1d4f8a')),'#fff3cf'),
  ('<rect width="144" height="190" fill="#20243a"/>'+waves(72,80)+g(72,180,.6,person('#1d4f8a',seat=True)),'#20243a')],['the noise','one ring','listening']),'A temple visit (an illustrative story).',
 ['Arjun swings the temple bell again and again. Clang, clang, clang.','Ajji takes his hand. “Once. Then listen until it is gone.”','He rings once. The sound fades and fades. When it is gone, the temple is very quiet, and so is Arjun.'])
endp=end(i,['<b>Name.</b> Ghaṇṭā, gaṇṭe; cast in bell metal.','<b>Kinds.</b> Doorway bells and hand bells with deity emblems.','<b>When.</b> Entering, bathing, incense, lamp, food, ārati.','<b>Why.</b> To invite the gods and drive away evil (common verse); to focus the mind.','<b>Vows.</b> Bells offered for wishes fulfilled.'],'Part 6 is pradakṣiṇā.','The first offering is sound')
